import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CmvPqeTF.js";const f=JSON.parse('{"title":"远程文件编辑","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md","lastUpdated":1788361893000}'),r={name:"guide/editor.md"};function l(i,t,c,s,h,n){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="远程文件编辑" tabindex="-1">远程文件编辑 <a class="header-anchor" href="#远程文件编辑" aria-label="Permalink to &quot;远程文件编辑&quot;">​</a></h1><p>vShell 内置 Monaco Editor，可以直接编辑<strong>远程文件</strong>（经 SFTP 读写）与<strong>本地文件</strong>，保存即写回。</p><hr><h2 id="_1-打开文件" tabindex="-1">1. 打开文件 <a class="header-anchor" href="#_1-打开文件" aria-label="Permalink to &quot;1. 打开文件&quot;">​</a></h2><p>在 <a href="./sftp.html">SFTP 面板</a>中<strong>双击</strong>文件即可打开：</p><table tabindex="0"><thead><tr><th>来源</th><th>标签前缀</th><th>读取</th><th>保存（⌘S / Ctrl+S）</th></tr></thead><tbody><tr><td>远端文件</td><td><code>[远端]</code> + 蓝</td><td><code>SFTPReadFileContent</code></td><td><code>SFTPWriteFileContent</code> 写回服务器</td></tr><tr><td>本地文件</td><td><code>[本地]</code> + 绿</td><td><code>ReadLocalFileContent</code></td><td><code>WriteLocalFileContent</code> 写回本机</td></tr><tr><td><code>~/.ssh/config</code></td><td>编辑器标签</td><td><code>ReadSSHConfigRaw</code></td><td><code>WriteSSHConfigRaw</code>，并刷新 SSH 配置面板</td></tr></tbody></table><ul><li>标签悬停 Tooltip 显示完整路径（远端为 <code>user@host:/path</code>）</li><li>同一文件重复打开时直接切换到已有标签，不会开第二个</li></ul><h3 id="可编辑性限制" tabindex="-1">可编辑性限制 <a class="header-anchor" href="#可编辑性限制" aria-label="Permalink to &quot;可编辑性限制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>限制</th><th>说明</th></tr></thead><tbody><tr><td>大小上限</td><td><strong>5 MB</strong>（远端与本地相同），超过提示「文件过大，不支持编辑」</td></tr><tr><td>二进制类型</td><td>按扩展名黑名单拦截（图片 / 压缩包 / 可执行文件等），提示「该文件类型不支持编辑」</td></tr></tbody></table><h2 id="_2-语言识别" tabindex="-1">2. 语言识别 <a class="header-anchor" href="#_2-语言识别" aria-label="Permalink to &quot;2. 语言识别&quot;">​</a></h2><p>按扩展名自动检测，覆盖 40+ 种语言：<code>ts / js / json / html / css / scss / vue / md / yaml / xml / go / py / java / c / cpp / rust / ruby / php / sh / sql / toml / dockerfile / tf / lua / swift / kt / scala / r / dart</code> 等；对 <code>Makefile</code>、<code>Dockerfile</code>、<code>CMakeLists.txt</code> 做文件名特判，其余兜底纯文本。</p><h2 id="_3-编辑器行为" tabindex="-1">3. 编辑器行为 <a class="header-anchor" href="#_3-编辑器行为" aria-label="Permalink to &quot;3. 编辑器行为&quot;">​</a></h2><ul><li>主题跟随应用明暗（<code>vs-dark</code> / <code>vs</code>），字号 13、自动换行、显示行号、<strong>无 minimap</strong></li><li>内容一有修改，标签标题出现橙色 <code>•</code>（未保存标记）</li><li><code>⌘S</code> 保存当前标签；原生菜单 File → Save（同样 <code>⌘S</code>）只对<strong>当前激活</strong>的编辑器标签生效</li></ul><h2 id="_4-注意事项" tabindex="-1">4. 注意事项 <a class="header-anchor" href="#_4-注意事项" aria-label="Permalink to &quot;4. 注意事项&quot;">​</a></h2><ul><li>关闭有未保存修改的标签<strong>没有确认提示</strong>，改动会直接丢失——养成先保存的习惯</li><li>无「另存为」能力</li><li>保存采用整文件覆写（<code>Create</code> + 单次 <code>Write</code>），并非增量 diff</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./sftp.html">SFTP 文件管理</a> —— 文件的浏览入口</li><li><a href="./ssh-config.html">~/.ssh/config 导入导出</a> —— config 原文编辑</li></ul>',18)])])}const _=e(r,[["render",l]]);export{f as __pageData,_ as default};
